#ifndef GAME_H
#define GAME_H
#include <stdint.h>

/* Original linear addresses of the LE objects (DOS/4GW). The host maps a copy
 * at game_image and applies the LE fixups for that load address. */
#define OBJ1_BASE     0x10000u
#define OBJ1_SIZE     0xD28A0u
#define OBJ2_BASE     0xF0000u
#define OBJ2_SIZE     0x34u
#define OBJ3_BASE     0x100000u
#define OBJ3_SIZE     0x18u
#define OBJ4_BASE     0x110000u
#define OBJ4_SIZE     0x99260u
#define GAME_SPAN     (OBJ4_BASE + OBJ4_SIZE - OBJ1_BASE)

#include "game_syms.h"   /* SYM_<label>: generated by tools/build/gen_port_syms.py */
#define ORIG_START         SYM_start
#define ORIG_INITRTNS      SYM___InitRtns
#define ORIG_CMAIN         SYM___CMain
#define ORIG_HOOK387       SYM___hook387
#define ORIG_UNHOOK387     SYM___unhook387
#define ORIG_SETENVP       SYM___setenvp_
#define ORIG_SETDEADLINE   SYM_SetTickDeadline
#define ORIG_WAITTICKS     SYM_WaitTicks
#define ORIG_WAITDEADLINE  SYM_WaitTickDeadline   /* WaitTickDeadline: spin until tickcount reaches the deadline */
#define ORIG_DEADLINEPASSED SYM_TickDeadlinePassed  /* TickDeadlinePassed: has tickcount reached the deadline? */
#define ORIG_WAITRETRACE   SYM_WaitRetrace   /* WaitRetrace: busy-wait for VGA vertical retrace (TGV palette frames) */
#define ORIG_WAITRETRACE2  SYM_WaitRetraceEdges   /* WaitRetraceEdges: same, always both edges */
#define ORIG_WAITRETRACE3  SYM_WaitDisplayRetrace   /* wait display-enable then retrace */
#define ORIG_TGV_PALFLAG   SYM_tgvpalpending  /* tgvpalpending: TGV has a palette chunk for this frame */
#define ORIG_VIDSAVE       SYM_SaveTextMode
#define ORIG_VIDRESTORE    SYM_RestoreTextMode
#define ORIG_TICKCOUNT     SYM_tickcount
#define ORIG_TICKDEADLINE  SYM_tickdeadline
#define ORIG_CMDLINE       SYM_unk_1A1258
#define ORIG_CRT_ESP       SYM__STACKTOP
#define ORIG_CRT_ESP2      SYM__curbrk
#define ORIG_CRT_ESP3      SYM__dynend
#define ORIG_CRT_SEL       SYM__psp
#define ORIG_CRT_CMD       SYM_dword_124414
#define ORIG_CRT_CMDEND    SYM__STACKLOW
#define ORIG_CRT_CMDLINAL  SYM__LpCmdLine
#define ORIG_CRT_DOSMAJ    SYM__osmajor
#define ORIG_CRT_DOSMIN    SYM__osminor
#define ORIG_CRT_IS4G      SYM__Extender
#define ORIG_CRT_FLAT      SYM__ExtenderSubtype
#define ORIG_CRT_ENV       SYM__Envptr
#define ORIG_CRT_ENVSEL    SYM__Envptr_w4
#define ORIG_CRT_NO87      SYM___no87
/* Below 1 MB: the command line and the environment strings the C library keeps pointers into, then the DOS memory pool
 * (dos.c). The pool must not overlap them: the game takes all the DOS memory it can get and writes over it, which erased the
 * environment, so the sound driver's getenv("BLASTER") found nothing and the game started without sound. */
#define LOW_CMDLINE        0x20000u
#define LOW_ENVBLOCK       0x22000u
#define LOW_DOS_POOL       0x24000u
#define ORIG_SND_CARD      SYM_sndcard  /* sndcard: the sound driver StartSoundCard started (-1: none) */
#define ORIG_SND_DRIVER    SYM_snddriver  /* snddriver: the driver table index SndSetDriver made current (0: none) */
#define ORIG_SND_FLAGS     SYM_byte_11D1DE  /* dword_11D1DE: the sound code's state bits */
#define ORIG_TIMER_LIST    SYM_timercallbacks  /* timercallbacks: the 8 callbacks the timer interrupt (TimerISR) calls */
#define ORIG_CFG_SOUND     SYM_globalset  /* globalset: GLOBAL.SET options (bits 0-2 the card) */
#define ORIG_GETDS_SEL     SYM___saved_DS   /* __GETDS: mov ds, cs:[this word] (interrupt handlers) */

extern uint8_t *game_image;            /* mapped bytes for orig OBJ1_BASE .. end */
extern int32_t game_slide;             /* runtime_addr - original_linear */
extern uint8_t *game_code;             /* start of object 1 in the map */
extern uint32_t game_code_size;

#define GAME_ADDR(orig) ((uint8_t *)((uintptr_t)(orig) + (uintptr_t)game_slide))
#define ORIG_FROM(p)    ((uint32_t)((uintptr_t)(p) - (uintptr_t)game_slide))
#define IN_GAME_CODE(p) ((uintptr_t)(p) >= (uintptr_t)game_code && (uintptr_t)(p) < (uintptr_t)game_code + game_code_size)

int game_load(void);                   /* map the LE objects of HOCKEY.EXE */
const char *game_exe_path(void);

#endif
